mapper.select:
SELECT b.BOOK_ID, b.ACCOUNT_CODE, a.ACCOUNT_NAME, b.PERIOD, b.CURRENCY_CODE, b.BEGINNING_DEBIT, b.BEGINNING_CREDIT, b.PERIOD_DEBIT, b.PERIOD_CREDIT, b.ENDING_DEBIT, b.ENDING_CREDIT, a.ACCOUNT_LEVEL, a.ACCOUNT_TYPE, a.IS_LEAF, b.UPDATE_TIME FROM TBL_ACCOUNT_BALANCE b LEFT JOIN TBL_ACCOUNT_SUBJECT a ON b.ACCOUNT_CODE = a.ACCOUNT_CODE AND b.BOOK_ID = a.BOOK_ID WHERE 1=1
AND b.BOOK_ID = #{param.bookId}
AND b.ACCOUNT_CODE LIKE #{param.accountCode}||'%'
AND a.IS_LEAF = 'Y'
AND a.ACCOUNT_NAME LIKE '%'||#{param.accountName}||'%'
AND b.PERIOD = #{param.period}
AND b.CURRENCY_CODE = #{param.currencyCode}
AND a.ACCOUNT_TYPE = #{param.accountType}
AND a.ACCOUNT_LEVEL = #{param.accountLevel}
ORDER BY b.ACCOUNT_CODE, b.CURRENCY_CODE OFFSET #{param.offset} ROWS FETCH NEXT #{param.pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_ACCOUNT_BALANCE b
LEFT JOIN TBL_ACCOUNT_SUBJECT a ON b.ACCOUNT_CODE = a.ACCOUNT_CODE AND b.BOOK_ID = a.BOOK_ID
WHERE 1=1

    AND b.BOOK_ID = #{param.bookId}


    AND b.ACCOUNT_CODE LIKE #{param.accountCode}||'%'

        AND a.IS_LEAF = 'Y'



    AND a.ACCOUNT_NAME LIKE '%'||#{param.accountName}||'%'


    AND b.PERIOD = #{param.period}


    AND b.CURRENCY_CODE = #{param.currencyCode}


    AND a.ACCOUNT_TYPE = #{param.accountType}


    AND a.ACCOUNT_LEVEL = #{param.accountLevel}

mapper.update:
UPDATE TBL_ACCOUNT_BALANCE
SET
    BEGINNING_DEBIT = #{balanceData.beginningDebit, jdbcType=DECIMAL},
    BEGINNING_CREDIT = #{balanceData.beginningCredit, jdbcType=DECIMAL},
    PERIOD_DEBIT = #{balanceData.periodDebit, jdbcType=DECIMAL},
    PERIOD_CREDIT = #{balanceData.periodCredit, jdbcType=DECIMAL},
    ENDING_DEBIT = #{balanceData.endingDebit, jdbcType=DECIMAL},
    ENDING_CREDIT = #{balanceData.endingCredit, jdbcType=DECIMAL},
    UPDATE_TIME = SYSDATE
WHERE BOOK_ID = #{balanceData.bookId, jdbcType=BIGINT}
AND ACCOUNT_CODE = #{balanceData.accountCode, jdbcType=VARCHAR}
AND PERIOD = #{balanceData.period, jdbcType=VARCHAR}
AND CURRENCY_CODE = #{balanceData.currencyCode, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM TBL_ACCOUNT_BALANCE
WHERE BOOK_ID = #{bookId}
AND ACCOUNT_CODE = #{accountCode}
AND PERIOD = #{period}
AND CURRENCY_CODE = #{currencyCode}

mapper.select:
SELECT ADJUSTMENT_ID, BOOK_ID, ACCOUNT_CODE, ACCOUNT_NAME, PERIOD, CURRENCY_CODE, ADJUSTMENT_TYPE, ADJUSTMENT_AMOUNT, ORIGINAL_BEGINNING_DEBIT, ORIGINAL_BEGINNING_CREDIT, ORIGINAL_PERIOD_DEBIT, ORIGINAL_PERIOD_CREDIT, NEW_BEGINNING_DEBIT, NEW_BEGINNING_CREDIT, NEW_PERIOD_DEBIT, NEW_PERIOD_CREDIT, ADJUSTMENT_REASON, ATTACHMENT_PATH, STATUS, APPLICANT_ID, APPLICANT_NAME, APPLY_TIME, APPROVER_ID, APPROVER_NAME, APPROVAL_TIME, APPROVAL_COMMENT, REMARK, CREATE_TIME, UPDATE_TIME FROM TBL_BALANCE_ADJUSTMENT WHERE 1=1
AND BOOK_ID = #{param.bookId}
AND ACCOUNT_CODE LIKE #{param.accountCode}||'%'
AND PERIOD = #{param.period}
AND ADJUSTMENT_TYPE = #{param.adjustmentType}
AND STATUS = #{param.status}
ORDER BY CREATE_TIME DESC OFFSET #{param.offset} ROWS FETCH NEXT #{param.pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_BALANCE_ADJUSTMENT
WHERE 1=1

    AND BOOK_ID = #{param.bookId}


    AND ACCOUNT_CODE LIKE #{param.accountCode}||'%'


    AND PERIOD = #{param.period}


    AND ADJUSTMENT_TYPE = #{param.adjustmentType}


    AND STATUS = #{param.status}

SELECT COUNT(1) as totalRecords, NVL(SUM(BEGINNING_DEBIT), 0) as totalBeginningDebit, NVL(SUM(BEGINNING_CREDIT), 0) as totalBeginningCredit, NVL(SUM(PERIOD_DEBIT), 0) as totalPeriodDebit, NVL(SUM(PERIOD_CREDIT), 0) as totalPeriodCredit, NVL(SUM(ENDING_DEBIT), 0) as totalEndingDebit, NVL(SUM(ENDING_CREDIT), 0) as totalEndingCredit, COUNT(DISTINCT ACCOUNT_CODE) as accountCount, COUNT(DISTINCT CURRENCY_CODE) as currencyCount FROM TBL_ACCOUNT_BALANCE WHERE 1=1
AND BOOK_ID = #{param.bookId}
AND PERIOD = #{param.period}
AND CURRENCY_CODE = #{param.currencyCode}

SELECT ACCOUNT_CODE
FROM TBL_ACCOUNT_SUBJECT
WHERE BOOK_ID = #{bookId}
AND PARENT_ACCOUNT_CODE = #{parentAccountCode}
AND STATUS = 'ACTIVE'
ORDER BY ACCOUNT_CODE
